import{_ as l,l as o,o as e,c as R,v as i,p as n,x as t,d as O,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"RLOO 原文","description":"","frontmatter":{"title":"RLOO 原文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rloo-paper.md","filePath":"llm/rloo-paper.md","lastUpdated":1789023840000}'),P={name:"llm/rloo-paper.md"};function s(m,a,d,E,L,c){const r=o("Mermaid");return e(),R("div",null,[a[1]||(a[1]=i('<h1 id="rloo-原文" tabindex="-1">RLOO 原文 <a class="header-anchor" href="#rloo-原文" aria-label="Permalink to &quot;RLOO 原文&quot;">​</a></h1><div class="epigraph"><p>PPO 在 RLHF 里被当成默认锤子；奖励只打在整段完成上时，把整段当成一个动作，用 REINFORCE 加留一法基线，往往更简单也更强。</p><footer>—— Ahmadian 等，Back to Basics: Revisiting REINFORCE-Style Optimization for Learning from Human Feedback in LLMs，ACL 2024</footer></div><p>InstructGPT 以来，RLHF 的强化学习段几乎被写成 <a href="/llm/schulman-ppo">PPO</a>：token 当动作、前缀当状态、GAE、裁剪、价值头。Ahmadian 等人问：这些配件是为高方差、逐步奖励的深度强化学习准备的，而偏好奖励只在完整生成结束时出现，策略又已经过预训练与 SFT，动作分布高度集中。他们拆开 PPO，发现在 Anthropic HH 与 TL;DR、Llama 与 Pythia 上，带移动平均基线的朴素 REINFORCE 已经稳定优于 PPO；再把同一提示的 \\(k\\) 条在线样本做成 REINFORCE Leave-One-Out（RLOO，估计器来自 Kool 等 2019），进一步超过 PPO、<a href="/llm/dpo">DPO</a> 与 RAFT。本篇按 ACL 2024 原文写主张与公式；短述见 <a href="/llm/rloo">RLOO</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PPO 把生成建成逐步 MDP：除 EOS 外的 token 奖励只有 KL 项，终点才有 RM 分，再用 GAE 把信用分配回中间状态。作者认为这一建模在 RLHF 里常常是空的——没有真实的逐步奖励，价值函数是在拟合一个人为拆开的过程。低 \\(\\lambda\\) 的 GAE 用价值自举降方差、引入偏差，在他们的消融里反而不如 \\(\\lambda=1\\) 的整段回报。裁剪与损失归一化去掉之后，表现也不崩溃。结论写成：PPO 对预训练语言模型过重。</p><p>他们采用上下文老虎机视角：提示是状态，整段 \\(y\\) 是一个动作，优化 KL 整形后的序列奖励</p> \\[R(x,y)=r_\\phi(x,y)-\\beta\\log\\frac{\\pi_\\theta(y\\mid x)}{\\pi_{\\mathrm{ref}}(y\\mid x)}. \\]<p>REINFORCE 给出 \\(\\mathbb{E}[(R-b)\\nabla\\log\\pi_\\theta(y\\mid x)]\\)。\\(b\\) 不依赖当前这条 \\(y\\) 的随机性时，估计仍无偏。移动平均 \\(b_{\\mathrm{MA}}\\) 用历史上的奖励，便宜但跨提示、跨训练阶段会错位。留一法用同一提示上其它 \\(k-1\\) 条的均值当 \\(b\\)，提示条件化、逐步重估，代价是每提示多生成。</p><h3 id="ppo-的动机在-rlhf-里弱在哪" tabindex="-1">PPO 的动机在 RLHF 里弱在哪 <a class="header-anchor" href="#ppo-的动机在-rlhf-里弱在哪" aria-label="Permalink to &quot;PPO 的动机在 RLHF 里弱在哪&quot;">​</a></h3><p>经典控制里策略随机、逐步有奖励、需要强正则压方差。SFT 之后的 LLM 下一步只在极少 token 上有质量，搜索空间名义上是词表的长度次方，实际上被先验削掉。作者把这当作减少方差控制、去掉 critic 的理由。这是经验主张，绑定他们的模型尺度与任务，不是「PPO 在任何 LLM 上多余」的定理。文中 PPO 对 REINFORCE 的败北幅度按设定在约 3% 到 20% 的胜率区间，具体以论文表为准。</p><p><span class="marginnote">RLOO 估计器不是这篇论文发明的。Kool, van Hoof, Welling，<em>Buy 4 REINFORCE Samples, Get a Baseline for Free!</em>（2019）把它写在一般策略梯度里。Ahmadian 等人的贡献是论证它适合 LLM 偏好学习，并与 PPO/DPO/RAFT 做系统比较。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个 \\(x\\) 从当前 \\(\\pi_\\theta\\) 采 \\(y^{(1)},\\ldots,y^{(k)}\\)，得分 \\(R^{(i)}\\)。RLOO 梯度为</p> \\[\\frac1k\\sum_{i=1}^{k}\\Biggl(R(y^{(i)},x)-\\frac1{k-1}\\sum_{j\\neq i}R(y^{(j)},x)\\Biggr)\\nabla\\log\\pi_\\theta(y^{(i)}\\mid x). \\]<p>第 \\(i\\) 条的基线不含 \\(R^{(i)}\\)，无偏。向量化等价于 \\(\\frac{k}{k-1}(R^{(i)}-\\bar R)\\)。整段一个对数似然、一个优势，不按 token 拆 GAE。实验还包含只有 \\(b_{\\mathrm{MA}}\\) 的单样本 REINFORCE。对比方法：PPO（token 级 clip + GAE）、DPO（离线成对）、RAFT（同预算下取最高分做 SFT）。数据集：HH 与 TL;DR。模型：Llama 与 Pythia 系列。作者报告 RLOO 全面高于这些基线；在相同采样预算下，\\(k=2\\) 的 RLOO 可接近或超过 \\(k=4\\) 的 RAFT，即负例被利用而不只模仿冠军。他们对流畅度、多样性、标注噪声与 KL 系数做了多维分析，称 RLOO 对噪声和 \\(\\beta\\) 更稳健。</p>',15)),(e(),n(h,null,{default:t(()=>[p(r,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%8F%90%E7%A4%BA%20x%22%5D%20--%3E%20K%5B%22%E5%9C%A8%E7%BA%BF%E9%87%87%20k%20%E6%9D%A1%20y%22%5D%0A%20%20K%20--%3E%20R%5B%22RM%20%2B%20KL%20%E6%95%B4%E5%BD%A2%E5%BE%97%20R%22%5D%0A%20%20R%20--%3E%20LOO%5B%22b_i%20%3D%20%E5%85%B6%E4%BD%99%20k%E2%88%921%20%E6%9D%A1%E5%9D%87%E5%80%BC%22%5D%0A%20%20LOO%20--%3E%20RF%5B%22(R_i%20%E2%88%92%20b_i)%20%E2%88%87%20log%20%CF%80(y_i%7Cx)%22%5D%0A%20%20RF%20--%3E%20TH%5B%22%E6%9B%B4%E6%96%B0%E6%95%B4%E6%AE%B5%E7%AD%96%E7%95%A5%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[O(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h3 id="与-ppo、raft、dpo-并排" tabindex="-1">与 PPO、RAFT、DPO 并排 <a class="header-anchor" href="#与-ppo、raft、dpo-并排" aria-label="Permalink to &quot;与 PPO、RAFT、DPO 并排&quot;">​</a></h3><p>PPO：逐步比率与 critic，实现重，超参多。作者消融显示去掉 clip 与若干归一化后性能不降，支持「配件不是 RLHF 的必要复杂度」。RAFT：同组只强化赢家，采样信息的 \\(k-1\\) 条被丢。RLOO 每条都进梯度，冠军与亚军的相对差被保留。DPO：离线对，无在线探索；在他们的在线 RM 设定下弱于 RLOO。这不否证 DPO 在无 RM、纯离线预算下的价值，只说明「有在线奖励时简单策略梯度够用」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="留一法为何比移动平均更贴-rlhf" tabindex="-1">留一法为何比移动平均更贴 RLHF <a class="header-anchor" href="#留一法为何比移动平均更贴-rlhf" aria-label="Permalink to &quot;留一法为何比移动平均更贴 RLHF&quot;">​</a></h3><p>\\(b_{\\mathrm{MA}}\\) 混合不同提示的难度：简单提示的高分会抬高基线，使难题上的合格回答变成负优势。留一法的基线是「这道题上其它随机完成的平均」，难度对齐。\\(k=2\\) 时基线就是另一条的 \\(R\\)，优势是两条之差，很像成对比较，但两条都来自当前策略，且两条都更新。\\(k\\) 增大，基线方差下降，接近条件期望 \\(\\mathbb{E}[R\\mid x]\\)，仍不含自身，故仍无偏。含自身的组均值（<a href="/llm/grpo-paper">GRPO 原文</a> 常用）在 \\(k\\) 小时把 \\(R_i\\) 漏进 \\(b_i\\)，引入偏差； \\(k\\) 大时两者接近。DeepSeekMath 用 std 再缩放，RLOO 原文用减法保留绝对量纲，跨 batch 的学习率要对 \\(R\\) 的尺度敏感。</p><p>整段动作把 \\(\\nabla\\log\\pi(y\\mid x)\\) 写成 token 对数梯度之和乘同一优势，信用在序列上均匀。这正是作者放弃逐步 MDP 的点：他们实验认为不必对中间 token 学 \\(V\\)。若真正有逐步过程奖励，这一结论不适用，应回到 GAE 或过程监督 GRPO。</p><p><span class="marginnote">KL 整形写在序列 \\(R\\) 里，与 GRPO 把 KL 放进损失是不同实现。比较两条曲线时要看 \\(\\beta\\) 惩罚的是同一对象。原文强调 RLOO 对 \\(\\beta\\) 更不脆，仍须扫，不是可以去掉 KL。</span></p><h3 id="「建模部分完成是不必要的」这句话的范围" tabindex="-1">「建模部分完成是不必要的」这句话的范围 <a class="header-anchor" href="#「建模部分完成是不必要的」这句话的范围" aria-label="Permalink to &quot;「建模部分完成是不必要的」这句话的范围&quot;">​</a></h3><p>论文用实验支持：在偏好 RM 只打整段的设定下，老虎机 REINFORCE 不弱于 token-MDP PPO。范围不包括：逐步人类反馈、过程奖励、需要价值函数做方差规约的超长推理。也不包括「因此 GAE 在数学 RL 里永远有害」——那是另一篇工作的设定。引用时应带上 HH / TL;DR 与他们使用的 Llama、Pythia 尺度。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>RLOO 把 critic 显存换成 \\(k\\) 路生成。\\(k=1\\) 没有留一，只能退回 \\(b_{\\mathrm{MA}}\\)。在线 RM 必须与策略一起部署，离线 DPO 那条「两份前向」的省法不成立。无偏基线不自动无噪： \\(k\\) 小、RM 噪时，另一条的 \\(R\\) 会把优势打飞。作者报告相对 RAFT 对噪声更稳健，仍不是无噪声。</p><p>不要把后起的「RLOOTrainer 里再加 PPO epoch 与优势标准化」全部算进 ACL 原文。原文主张的是简单 REINFORCE 风格；库实现为了稳定可能加回 clip，那是工程分叉。与 GRPO 的关系：同属无 critic 组采样；GRPO 来自数学 RL、含 clip 与 std、KL 在损失里；RLOO 来自「回到 REINFORCE」、留一均值、序列级动作。选谁先看奖励是否已标准化、以及想不想要无偏基线。</p><p><span class="marginnote">胜率数字是相对他们训练的 RM 或裁判协议，不是 Arena 通用排名。文中「REINFORCE 胜过 PPO 3.2%–20.3%」是跨数据集–基座配对的区间，单次复现应报告具体配对，不要只引区间。</span></p><h3 id="何时不必上-rloo" tabindex="-1">何时不必上 RLOO <a class="header-anchor" href="#何时不必上-rloo" aria-label="Permalink to &quot;何时不必上 RLOO&quot;">​</a></h3><p>不能在线采样或没有 RM，用离线成对方法。已经为逐步过程奖励建了 critic，PPO/GAE 的建模不再「空」。\\(k\\) 只能为 1 时，留一法不存在。需要组内 z 分数对齐跨题量纲、且 \\(G\\) 很大，GRPO 的标准化可能更省学习率扫描。不要因为名字里有 REINFORCE 就从随机初始化开训——原文策略从 SFT 出发。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Ahmadian 等主张：RLHF 的序列级奖励使 token-MDP PPO 过重，简单 REINFORCE 即可。</li><li>RLOO 用同一提示上其它 \\(k-1\\) 条奖励的均值当无偏基线，估计器来自 Kool 等 2019。</li><li>整段视为一个动作，优势乘整条 \\(\\nabla\\log\\pi(y\\mid x)\\)；KL 写在序列奖励里。</li><li>在 HH、TL;DR 与 Llama/Pythia 上，报告优于 PPO、DPO、RAFT；对噪声与 \\(\\beta\\) 更稳。</li><li>去掉 PPO 的 clip 等配件在他们的消融里不降性能，不能直接外推到所有 LLM RL。</li><li>\\(k=1\\) 不是 RLOO；过程奖励设定不在原文范围内。</li><li>出处：Ahmadian, Cremer, Gallé, Fadaee, Kreutzer, Pietquin, Üstün, Hooker，<em>Back to Basics: Revisiting REINFORCE-Style Optimization for Learning from Human Feedback in LLMs</em>，ACL 2024，arXiv:2402.14740。</li></ul>',17))])}const b=l(P,[["render",s]]);export{k as __pageData,b as default};
